struct string_buf
{
  int data;
  int max_blocks;
  int char_length;
};

class stringx
{
  char *chars;
  string_buf *my_buf;

public:
  stringx();
  stringx(const char *str, int len = -1);
  ~stringx();

  const char *c_str() const { return chars; }
  int size() const { return my_buf->char_length; }
  int length() const;
  const char operator[](int i) const
  {
    if (i < 0)
      i += length();
    return chars[i];
  }
};

class os_file
{
  long long alignment;
  char storage[56];

public:
  enum { FILE_READ = 1 };
  ~os_file();
};

class text_file
{
  char storage[216];

public:
  ~text_file();
};

class chunk_file
{
public:
  enum { FILE_TEXT = 0x0100 };

  chunk_file();
  void open(const stringx &name, int flags = os_file::FILE_READ);
  void close();

private:
  int type;
  os_file binary;
  text_file text;
};

bool file_finder_exists(const stringx &filename, const stringx &extension,
                        stringx *found_name = 0);
void error(const char *format, ...);
extern "C" char *strncpy(char *destination, const char *source,
                         unsigned int count);

class animation_interface
{
  void read_animations(chunk_file &f, const stringx &anims_directory);

public:
  void read_anim_info_file(const stringx &anims_filename);
};

void animation_interface::read_anim_info_file( const stringx& anims_filename )
{
  int           i;
	chunk_file    f;
  stringx       filename;
  char          tc[256];

  if ( !file_finder_exists(anims_filename, stringx(".ani"), &filename) ) 
  {
    error("File '%s' not found!", anims_filename.c_str());
    return;
  }
  i = anims_filename.size();
  while( --i )
  {
    if( anims_filename[ i ] == '\\' )
      break;
  }
  strncpy( tc, anims_filename.c_str(), ++i );
  tc[i] = 0;
  stringx anims_directory( tc );

  f.open( filename, os_file::FILE_READ | chunk_file::FILE_TEXT );

  read_animations(f, anims_directory);

  f.close();
}
